/bin/zsh -lc "python3 - <<'PY'
import re
src=open('prog.pw9').read().splitlines()
p=[]
for line in src:
 s=line.split(';')[0].strip()
 if s:p.append(s.split())
regs=dict(a=0,b=0,c=0,d=0); pc=0; count=0; outs=[]
def val(x): return regs[x] if x in regs else int(x)
while 0<=pc<len(p):
 ins=p[pc]; op=ins[0]; count+=1; nxt=pc+1
 if op=='set': regs[ins[1]]=val(ins[2])%65536
 elif op=='add': regs[ins[1]]=(regs[ins[1]]+val(ins[2]))%65536
 elif op=='mul': regs[ins[1]]=(regs[ins[1]]*val(ins[2]))%65536
 elif op=='mod':
  x=val(ins[2])
  if x>0: regs[ins[1]]%=x
 elif op=='dec': regs[ins[1]]=max(0,regs[ins[1]]-1)
 elif op=='jnz':
  if val(ins[1])"'!=0:nxt=pc+val(ins[2])
 elif op=='"'skp':
  if val(ins[1])<val(ins[2]):nxt=pc+2
 elif op=='out': outs.append(val(ins[1]))
 pc=nxt
print(len(p), sum(outs),len(outs),count,regs)
print(outs[-10:])
open('answer.txt','w').write(f'{sum(outs)} {count}\\n')
PY
cat answer.txt"

